<template><div class="login-page flex flex-center"><q-card class="login-card"><div class="login-card__brand"><h1 class="login-card__title">เปลี่ยนรหัสผ่าน</h1></div><q-form class="login-card__form" @submit.prevent="submit"><q-input v-model="currentPassword" type="password" label="รหัสผ่านปัจจุบัน" outlined /><q-input v-model="newPassword" type="password" label="รหัสผ่านใหม่" outlined /><q-input v-model="confirm" type="password" label="ยืนยันรหัสผ่านใหม่" outlined /><q-banner v-if="message" dense rounded :class="success ? 'bg-positive text-white' : 'login-card__error'">{{ message }}</q-banner><q-btn type="submit" unelevated no-caps label="เปลี่ยนรหัสผ่าน" :loading="loading" class="login-card__submit" /></q-form></q-card></div></template>
<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { authApiService } from '@/services/auth-api.service'; import { useAuthStore } from '@/stores/auth-store';
const router = useRouter(); const auth = useAuthStore(); const currentPassword = ref(''); const newPassword = ref(''); const confirm = ref(''); const loading = ref(false); const message = ref(''); const success = ref(false);
async function submit(): Promise<void> { if (newPassword.value.length < 8 || newPassword.value !== confirm.value) { message.value = 'รหัสผ่านใหม่ต้องมีอย่างน้อย 8 ตัวอักษรและตรงกัน'; return; } loading.value = true; try { await authApiService.changePassword(currentPassword.value, newPassword.value); await auth.logout(); success.value = true; message.value = 'เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบใหม่'; setTimeout(() => void router.replace('/login'), 1000); } catch { message.value = 'รหัสผ่านปัจจุบันไม่ถูกต้อง'; } finally { loading.value = false; } }
</script>
